import dayjs from "dayjs";

// SPEC: spec-a6f59e
/** Mirrors SystemSettings.AutoGeneratedMatchNumber{Default,Min,Max} on the backend. */
export const DEFAULT_GENERATE_COUNT = 2;
export const MIN_GENERATE_COUNT = 1;
export const MAX_GENERATE_COUNT = 8;

/** A whole number from 1 to 8 - the only counts the Generate modal will run with. */
export const isValidGenerateCount = (count: number) =>
  Number.isInteger(count) && count >= MIN_GENERATE_COUNT && count <= MAX_GENERATE_COUNT;

/**
 * The dates the Generate modal creates Match Days on: the first `count` dates that fall on
 * `weekday` (dayjs .day() convention, 0 = Sunday), starting from the first one on or after the
 * 1st of `startMonth` ("YYYY-MM") and stepping a week at a time into later months as needed.
 * Empty for a missing/invalid month or a count outside 1-8, so the caller can't create a
 * partial or runaway batch.
 */
export const generateMatchDayDates = (startMonth: string, weekday: number, count: number): dayjs.Dayjs[] => {
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(startMonth ?? "")) return [];
  if (!Number.isInteger(weekday) || weekday < 0 || weekday > 6) return [];
  if (!isValidGenerateCount(count)) return [];

  const monthStart = dayjs(`${startMonth}-01`);
  if (!monthStart.isValid()) return [];

  const first = monthStart.add((weekday - monthStart.day() + 7) % 7, "day");
  return Array.from({ length: count }, (_, i) => first.add(i * 7, "day"));
};
